function answer(char){const s=state.active;if(!s)return;const task=s.tasks[s.index],w=byChar.get(task.char),q=s.question;if(!q||q.answered||q.wrong.includes(char))return;const p=s.results[w.char];if(char===w.char){q.answered=true;if(task.kind==='transfer')p.transfer=true;else p.recognized=true;chime('ok');navigator.vibrate?.(12);if(!p.hinted&&!p.mistakes){say(wordSpeech(w));clearTimeout(feedbackTimer);feedbackTimer=setTimeout(nextTask,1600);}}else{q.wrong.push(char);p.mistakes++;state.confusions.push({char:w.char,chosen:char,day:today()});state.confusions=state.confusions.slice(-80);if(q.wrong.length>=2){q.hint=true;p.hinted=true;}}save();renderQuestion(w,task.kind==='transfer');}
function nextTask(){clearTimeout(feedbackTimer);const s=state.active;if(!s)return;const task=s.tasks[s.index];if(['quiz','transfer'].includes(task.kind)&&!s.question?.answered)return;if(task.kind==='match'&&s.match&&s.match.matched.length<s.match.pairs.length)return;if(task.kind==='write'&&!['written','watched','writeSkipped'].some(k=>s.results[task.char][k]))return;stopWriter();stopSpeech();s.index++;s.question=null;s.learnStep=0;if(s.index>=s.tasks.length){state.placementNote='';const grownBefore=growthOf(secureCount()),visitedBefore=visitedThemes();const result=completeSession(state,s);result.grew=growthOf(secureCount())>grownBefore;result.visitors=visitedThemes().filter(u=>!visitedBefore.includes(u));if(result.chars.length)state.letters[today()]={chars:result.chars.slice(0,6),read:false};result.badges=awardBadges(state);save();route='complete';completionPage(result);nav();const quick=matchMedia('(prefers-reduced-motion: reduce)').matches;countUp(quick?0:1200);if(!quick)setTimeout(confetti,1300);else confetti();chime('done');return;}save();enter();studyPage();window.scrollTo({top:0,behavior:'instant'});}
// Progress is saved after every step, so a rest needs no confirmation.
