 const lower=WRITE_LEVELS[WRITE_LEVELS.indexOf(writeTry.mode)+1];
 const say=lower==='trace'?'小兔先把浅灰的字描出来，你沿着写就行。':lower==='guided'?'写错的那一笔会亮出来，你照着写。':lower==='watch'?'小兔一笔一笔写给你看，你看着写。':'小兔先把这个字写一遍给你看。';
