function weekDays(){const start=addDays(today(),-6);return Array.from({length:7},(_,i)=>addDays(start,i)).filter(d=>{const x=state.days[d];return x&&(x.newChars.length+x.reviewChars.length+x.written.length)>0;}).length;}
function countUp(delay=0){document.querySelectorAll('.count[data-to]').forEach(el=>{const to=Number(el.dataset.to),t0=performance.now()+delay;const tick=now=>{const k=Math.max(0,Math.min(1,(now-t0)/700));el.textContent=Math.round(to*(1-Math.pow(1-k,3)));if(k<1)requestAnimationFrame(tick);};if(matchMedia('(prefers-reduced-motion: reduce)').matches)el.textContent=to;else requestAnimationFrame(tick);});}
