function placementPage(){if(!placement)placement={tier:1,answers:[],misses:0,answered:false};if(!placement.char){placement.char=placementPick(WORDS,placement.tier,placement.answers.map(a=>a.char))||placementPick(WORDS,2,placement.answers.map(a=>a.char));placement.choices=optionsFor(byChar.get(placement.char),WORDS);placement.spoken=false;}const w=byChar.get(placement.char);app.innerHTML=`<div class="practice"><div class="practice-top"><button class="text-button" data-act="placementSkip">${icon('back')} 从基础开始</button><span class="pill">认认看 · 第 ${placement.answers.length+1} 题</span></div><section class="card study-card"><h2>听一听，选一个字</h2><button class="button soft" style="margin-top:18px" data-act="say" data-text="${esc(wordSpeech(w))}">${icon('sound')} 重听</button><div class="choices">${placement.choices.map(c=>`<button class="choice ${placement.answered&&c===placement.picked?'selected':''}" data-act="placementAnswer" data-char="${c}" ${placement.answered?'disabled':''}>${c}</button>`).join('')}</div><div class="feedback" aria-live="polite">${placement.answered?`${buddy('idle')}<span class="neutral">${placement.picked==='?'?'没关系，看下一题':'好，看下一题'}</span>`:''}</div><div class="study-footer">${placement.answered?'':'<button class="text-button" data-act="placementAnswer" data-char="?">我还不确定</button>'}</div></section></div>`;if(!placement.spoken){placement.spoken=true;speak(wordSpeech(w),()=>{});}}
