const GAME_ROUNDS=[{sets:[['清','氵'],['晴','日'],['情','忄']],clue:'这三个字都有“青”，看看它们的左边。',result:'“氵”常与水有关，“日”常与太阳有关，“忄”常与心情有关。'},{sets:[['妈','女'],['河','氵'],['林','木']],clue:'看看字的左边，它能告诉你一个意思线索。',result:'“女”在“妈”里，“氵”在“河”里，“木”在“林”里。'},{sets:[['跑','足'],['猫','犭'],['花','艹']],clue:'想想跑步的脚、动物和植物。',result:'“足”与脚有关，“犭”常见于动物字，“艹”常见于植物字。'},{sets:[['请','讠'],['雪','雨'],['椅','木']],clue:'想想说话、天气和木头。',result:'“讠”与说话有关，“雨”与天气有关，“木”常见于木制物品。'},{sets:[['海','氵'],['蝶','虫'],['狗','犭']],clue:'大海、蝴蝶、小狗，各自和什么有关？',result:'“氵”与水有关，“虫”常见于小虫子，“犭”常见于动物字。'},{sets:[['饭','饣'],['铅','钅'],['笔','竹']],clue:'想想吃饭、金属和竹子。',result:'“饣”与食物有关，“钅”与金属有关，“竹”常见于竹子做的东西。'},{sets:[['跳','足'],['唱','口'],['笑','竹']],clue:'跳用脚，唱用什么，笑起来像什么？',result:'“足”与脚有关，“口”与嘴和声音有关，“竹”常见于竹子做的东西。'},{sets:[['家','宀'],['冷','冫'],['远','辶']],clue:'房顶、冰块、走路。',result:'“宀”常与房屋有关，“冫”与寒冷有关，“辶”与走路、距离有关。'},{sets:[['花','艹'],['看','目'],['说','讠']],clue:'花是什么？用什么看？用什么说？',result:'“艹”常与植物有关，“目”与眼睛有关，“讠”与说话有关。'},{sets:[['林','木'],['雪','雨'],['烧','火']],clue:'树林、下雪、烧火。',result:'“木”与树木有关，“雨”与天气有关，“火”与光亮和燃烧有关。'}];
